const NORMAL_EPS = 1e-3;
const PLANE_REL_EPS = 1e-3;
const COLLINEAR_REL_EPS = 1e-3;
/**
 * Losslessly reduce coplanar regions of a marching-cubes mesh by
 * topology-preserving vertex removal.
 *
 * For a closed manifold MC mesh, a vertex `v` is "lossless-removable" iff
 * its incident-tri fan, walked in cyclic order, falls into one of:
 *
 * 1. K=1 coplanar fan. Every triangle in v's fan lies on the same plane
 *    (same unit normal and same plane offset, within tolerance). Removing
 *    v is the inverse of vertex split: re-triangulate the boundary
 *    polygon in the same plane.
 *
 * 2. K=2 collinear seam. The fan splits into exactly two contiguous
 *    coplanar arcs (different planes). The two crease vertices `a` and
 *    `b` (the boundary points where the plane changes around v) are
 *    collinear with v in 3D, with v between them. Removing v collapses
 *    the two crease edges (v-a, v-b) into a single straight edge (a-b)
 *    that lies in both planes; each arc's polygon re-triangulates
 *    without v.
 *
 * Vertices with K >= 3 (multi-way corners) are kept.
 *
 * Removing a removable v is exact-lossless: the surface footprint is
 * identical, no vertex moves and none are created. The transformation
 * is the inverse of vertex split, so it is topology-preserving by
 * construction:
 *
 * - No T-junctions. Every old vertex on the polygon boundary remains a
 *   vertex of every triangle that previously touched it. Adjacent fused
 *   regions and verbatim regions stay coupled at every shared vertex.
 * - Watertight. The closed manifold structure is preserved across
 *   removal. Both the K=1 and K=2 cases preserve the K=2 seam edge as
 *   a single shared edge between the two plane groups.
 * - Bit-exact. Every output position is a verbatim copy of an input
 *   position; no vertex is fabricated.
 *
 * Algorithm:
 *
 * 1. Build per-vertex incident-tri lists and per-tri normalized normals
 *    and plane offsets.
 * 2. Process vertices via a dirty-flag worklist. Initially queue every
 *    vertex; after a successful removal, re-queue the ring neighbours
 *    so chains of K=1 / K=2 vertices collapse in one run.
 * 3. For each dequeued vertex `v`:
 *      a. Walk the fan to extract the cyclic ring vertices and the
 *         cyclic ordered tris (each tri (v, ring[i], ring[(i+1)%k]) is
 *         the i-th tri in fan order).
 *      b. Decide K. If all tris share a plane: K=1. Otherwise count
 *         transitions in cyclic order; K=2 if exactly two arcs.
 *      c. K>=3: skip. K=2: verify ring[i1], v, ring[i2] are collinear.
 *      d. For each arc, project its polygon to 2D using the arc's
 *         plane basis, ear-clip, and append the new tris.
 *      e. Mark v's old tris dead, register the new tris in each polygon
 *         vertex's incident list, and re-queue the ring.
 * 4. Compact: drop dead tris and unused vertices, remap indices.
 *
 * @param mesh - Input triangle mesh from {@link marchingCubes}.
 * @param voxelResolution - Size of one voxel in world units. Used to scale the plane-offset tolerance. (The K=2 collinearity check is purely angular and has no voxel-scaled term.)
 * @returns A new mesh with the same surface geometry, no T-junctions, and far fewer triangles.
 */
const coplanarMerge = (mesh, voxelResolution) => {
    const { positions, indices } = mesh;
    const inputTriCount = (indices.length / 3) | 0;
    const vertCount = (positions.length / 3) | 0;
    if (inputTriCount === 0) {
        return { positions: new Float32Array(0), indices: new Uint32Array(0) };
    }
    // Plane-offset tolerance for the coplanarity test. An absolute floor
    // (voxelResolution * PLANE_REL_EPS) handles near-origin planes, while
    // a relative term scaled by max(|da|, |db|) handles large-offset
    // planes where Float32 position precision in d = n . p causes
    // relative error proportional to |d|. Without the relative term,
    // coplanar fans far from the origin would be seen as distinct planes.
    const planeEps = (da, db) => {
        const absA = da < 0 ? -da : da;
        const absB = db < 0 ? -db : db;
        return PLANE_REL_EPS * (voxelResolution + (absA > absB ? absA : absB));
    };
    // Mutable triangle table. Flat typed arrays so we can append new tris
    // (from ear-clipping) without per-tri allocations and without hitting
    // V8's regular-Array backing-store size cap on large meshes.
    // `triVertsArr` indexes are 3*t, everything else is t.
    //
    // Normals are stored as Float32 (unit vectors; ample precision for the
    // dot-product coplanarity test against `1 - NORMAL_EPS`). The plane
    // offset stays Float64 since it's an absolute world-space scalar that
    // can be large for distant scenes.
    let triCap = inputTriCount;
    let triVertsArr = new Uint32Array(triCap * 3);
    let triNxArr = new Float32Array(triCap);
    let triNyArr = new Float32Array(triCap);
    let triNzArr = new Float32Array(triCap);
    let triDArr = new Float64Array(triCap);
    let triAliveArr = new Uint8Array(triCap);
    let triCount = inputTriCount;
    // Capacity-doubling appenders for new tris generated by ear-clipping.
    const ensureTriCap = () => {
        if (triCount < triCap)
            return;
        const newCap = triCap * 2;
        const growF32 = (src) => {
            const out = new Float32Array(newCap);
            out.set(src);
            return out;
        };
        const growF64 = (src) => {
            const out = new Float64Array(newCap);
            out.set(src);
            return out;
        };
        const newVerts = new Uint32Array(newCap * 3);
        newVerts.set(triVertsArr);
        triVertsArr = newVerts;
        triNxArr = growF32(triNxArr);
        triNyArr = growF32(triNyArr);
        triNzArr = growF32(triNzArr);
        triDArr = growF64(triDArr);
        const aliveOut = new Uint8Array(newCap);
        aliveOut.set(triAliveArr);
        triAliveArr = aliveOut;
        triCap = newCap;
    };
    // Pass 0: compute per-tri normalized normal and plane offset.
    for (let t = 0; t < inputTriCount; t++) {
        const ia = indices[t * 3];
        const ib = indices[t * 3 + 1];
        const ic = indices[t * 3 + 2];
        triVertsArr[t * 3] = ia;
        triVertsArr[t * 3 + 1] = ib;
        triVertsArr[t * 3 + 2] = ic;
        const ax = positions[ia * 3];
        const ay = positions[ia * 3 + 1];
        const az = positions[ia * 3 + 2];
        const bx = positions[ib * 3];
        const by = positions[ib * 3 + 1];
        const bz = positions[ib * 3 + 2];
        const cx = positions[ic * 3];
        const cy = positions[ic * 3 + 1];
        const cz = positions[ic * 3 + 2];
        const ex = bx - ax, ey = by - ay, ez = bz - az;
        const fx = cx - ax, fy = cy - ay, fz = cz - az;
        let nx = ey * fz - ez * fy;
        let ny = ez * fx - ex * fz;
        let nz = ex * fy - ey * fx;
        const nLen = Math.sqrt(nx * nx + ny * ny + nz * nz);
        if (nLen < 1e-12) {
            // Degenerate input tri; drop it from the active set.
            triAliveArr[t] = 0;
            continue;
        }
        const inv = 1 / nLen;
        nx *= inv;
        ny *= inv;
        nz *= inv;
        triNxArr[t] = nx;
        triNyArr[t] = ny;
        triNzArr[t] = nz;
        triDArr[t] = nx * ax + ny * ay + nz * az;
        triAliveArr[t] = 1;
    }
    // Per-vertex incident-tri lists, stored as a singly-linked free-listed
    // node pool backed by typed arrays. Each pool node `n` holds:
    //   poolTri[n]  - the incident tri index
    //   poolNext[n] - next node in the same vertex's list (or -1 = end)
    // `vertHead[v]` is the head node for vertex v (or -1 if v has no
    // incident tris). Removed nodes are pushed onto the `freeHead` chain
    // for reuse, so the pool's max occupancy is the initial fan-mention
    // count (3 * inputTriCount): the worklist's K=1/K=2 collapses are
    // monotonically tri-reducing, so the free list serves all subsequent
    // ear-clip allocations without ever growing the backing arrays.
    //
    // Footprint: 8 B/node * 3 * inputTriCount + 4 B/vert * vertCount.
    // For 25.7M raw tris / 12.9M raw verts that's ~615 MB pool +
    // ~52 MB heads, vs ~1.4 GB for the prior `number[][]` adjacency
    // (V8 Array headers, FixedArray headers, hidden classes per inner
    // array all inflate the boxed-SMI payload).
    const poolCap = inputTriCount * 3;
    const poolTri = new Int32Array(poolCap);
    const poolNext = new Int32Array(poolCap);
    let poolLen = 0;
    let freeHead = -1;
    const vertHead = new Int32Array(vertCount).fill(-1);
    const allocNode = () => {
        if (freeHead !== -1) {
            const n = freeHead;
            freeHead = poolNext[n];
            return n;
        }
        return poolLen++;
    };
    const freeNode = (n) => {
        poolNext[n] = freeHead;
        freeHead = n;
    };
    const addTriToVert = (v, tri) => {
        const n = allocNode();
        poolTri[n] = tri;
        poolNext[n] = vertHead[v];
        vertHead[v] = n;
    };
    // O(degree) removal of `tri` from `v`'s incident list. Returns true
    // if found and removed.
    const removeTriFromVert = (v, tri) => {
        let prev = -1;
        let cur = vertHead[v];
        while (cur !== -1) {
            if (poolTri[cur] === tri) {
                const nxt = poolNext[cur];
                if (prev === -1)
                    vertHead[v] = nxt;
                else
                    poolNext[prev] = nxt;
                freeNode(cur);
                return true;
            }
            prev = cur;
            cur = poolNext[cur];
        }
        return false;
    };
    for (let t = 0; t < inputTriCount; t++) {
        if (triAliveArr[t] === 0)
            continue;
        addTriToVert(triVertsArr[t * 3], t);
        addTriToVert(triVertsArr[t * 3 + 1], t);
        addTriToVert(triVertsArr[t * 3 + 2], t);
    }
    // Build a right-handed tangent / bitangent basis (t, b) on the plane
    // with normal n, picking the cardinal axis least aligned with n to
    // avoid precision loss in the cross product. By construction
    // t x b = n, so a polygon traced CCW around +n in 3D projects to a
    // CCW polygon in (t, b) coordinates (positive 2D signed area).
    const buildBasis = (nx, ny, nz) => {
        const ax = Math.abs(nx);
        const ay = Math.abs(ny);
        const az = Math.abs(nz);
        let tx, ty, tz;
        if (ax <= ay && ax <= az) {
            // X axis least aligned: t = (1, 0, 0) x n
            tx = 0;
            ty = -nz;
            tz = ny;
        }
        else if (ay <= az) {
            // Y axis least aligned: t = (0, 1, 0) x n
            tx = nz;
            ty = 0;
            tz = -nx;
        }
        else {
            // Z axis least aligned: t = (0, 0, 1) x n
            tx = -ny;
            ty = nx;
            tz = 0;
        }
        const tlen = Math.sqrt(tx * tx + ty * ty + tz * tz);
        const inv = 1 / tlen;
        tx *= inv;
        ty *= inv;
        tz *= inv;
        // bitangent = n x t (unit length because n and t are unit and
        // perpendicular).
        const bx = ny * tz - nz * ty;
        const by = nz * tx - nx * tz;
        const bz = nx * ty - ny * tx;
        return [tx, ty, tz, bx, by, bz];
    };
    // Reusable scratch buffers for extractFan. With typical MC fan sizes
    // (k <= ~12), a linear scan over parallel typed arrays is cheaper than
    // the Map-of-Map-of-Set allocations the previous version paid per
    // vertex, and saves ~3 allocations per worklist iteration on meshes
    // with tens of millions of vertices.
    let fanScratchCap = 16;
    let fanFromScratch = new Int32Array(fanScratchCap);
    let fanToScratch = new Int32Array(fanScratchCap);
    let fanTriScratch = new Int32Array(fanScratchCap);
    let fanRingScratch = new Int32Array(fanScratchCap);
    let fanTrisScratch = new Int32Array(fanScratchCap);
    const growFanScratch = (need) => {
        if (need <= fanScratchCap)
            return;
        let c = fanScratchCap;
        while (c < need)
            c *= 2;
        fanFromScratch = new Int32Array(c);
        fanToScratch = new Int32Array(c);
        fanTriScratch = new Int32Array(c);
        fanRingScratch = new Int32Array(c);
        fanTrisScratch = new Int32Array(c);
        fanScratchCap = c;
    };
    // Walk v's fan to extract its cyclic boundary polygon AND the matching
    // cyclic ordered tris. ring[i] is the "from" vertex of the i-th tri
    // (in fan order), and tris[i] = (v, ring[i], ring[(i+1) % k]) is the
    // tri whose two non-v vertices are ring[i] and ring[(i+1) % k].
    // Returns null when the fan is non-manifold (duplicate from-vertex,
    // closes prematurely, or fails to close).
    //
    // Output aliases the module-level `fanRingScratch` / `fanTrisScratch`
    // buffers; the caller must consume them before the next extractFan
    // call. `k` is returned explicitly since the scratch buffers may be
    // oversized.
    const extractFan = (v) => {
        let k = 0;
        for (let n = vertHead[v]; n !== -1; n = poolNext[n])
            k++;
        if (k < 3)
            return -1;
        growFanScratch(k);
        // Collect (from, to, tri) triples into parallel scratch arrays.
        // The O(k^2) duplicate-from scan here and the O(k^2) cyclic walk
        // below are cheap for small k and avoid per-vertex Map allocs.
        let i = 0;
        for (let n = vertHead[v]; n !== -1; n = poolNext[n]) {
            const t = poolTri[n];
            const a = triVertsArr[t * 3];
            const b = triVertsArr[t * 3 + 1];
            const c = triVertsArr[t * 3 + 2];
            let from, to;
            if (a === v) {
                from = b;
                to = c;
            }
            else if (b === v) {
                from = c;
                to = a;
            }
            else {
                from = a;
                to = b;
            }
            for (let j = 0; j < i; j++) {
                if (fanFromScratch[j] === from)
                    return -1;
            }
            fanFromScratch[i] = from;
            fanToScratch[i] = to;
            fanTriScratch[i] = t;
            i++;
        }
        const start = fanFromScratch[0];
        let cur = start;
        for (let step = 0; step < k; step++) {
            fanRingScratch[step] = cur;
            let found = -1;
            for (let j = 0; j < k; j++) {
                if (fanFromScratch[j] === cur) {
                    found = j;
                    break;
                }
            }
            if (found === -1)
                return -1;
            fanTrisScratch[step] = fanTriScratch[found];
            const next = fanToScratch[found];
            // Premature cycle close => fan is non-manifold (multi-component).
            if (next === start && step < k - 1)
                return -1;
            cur = next;
        }
        if (cur !== start)
            return -1;
        return k;
    };
    // Reusable scratch for earClip's doubly-linked polygon traversal.
    // Grows to the largest polygon seen and is reused across every
    // worklist iteration.
    let earPrevScratch = new Int32Array(16);
    let earNextScratch = new Int32Array(16);
    const growEarInternalScratch = (n) => {
        if (n <= earPrevScratch.length)
            return;
        let c = earPrevScratch.length;
        while (c < n)
            c *= 2;
        earPrevScratch = new Int32Array(c);
        earNextScratch = new Int32Array(c);
    };
    // Ear-clip a planar simple polygon. `px, py` are the projected 2D
    // coordinates of the first `n` polygon vertices (in CCW order); the
    // arrays may be larger than `n` (scratch-buffer aliasing is fine,
    // only [0, n) is read). Writes (n - 2) * 3 polygon-relative vertex
    // indices into `out[outOffset..]` and returns the number of indices
    // written on success, or -1 if the polygon is degenerate / not
    // simple.
    //
    // Strictly-collinear interior vertices (cross product == 0) are not
    // considered convex ear apices and so produce slivers as side
    // vertices of neighbouring ears. These are transient: any such
    // vertex is itself K=1 in the same plane and the worklist removes
    // it in a subsequent iteration, replacing the slivers with a clean
    // re-triangulation of its updated fan. An in-earClip pre-pass that
    // drops the vertex from this polygon would create a T-junction
    // with the vertex's other incident tris (which still reference it),
    // so we leave the cleanup to the worklist.
    const earClip = (px, py, n, out, outOffset) => {
        if (n < 3)
            return -1;
        if (n === 3) {
            out[outOffset] = 0;
            out[outOffset + 1] = 1;
            out[outOffset + 2] = 2;
            return 3;
        }
        // Verify CCW orientation. By construction (right-handed basis)
        // valid input polygons are CCW with positive signed area.
        let area2 = 0;
        for (let i = 0; i < n; i++) {
            const j = (i + 1) % n;
            area2 += px[i] * py[j] - px[j] * py[i];
        }
        if (area2 <= 0)
            return -1;
        growEarInternalScratch(n);
        const prev = earPrevScratch;
        const next = earNextScratch;
        for (let i = 0; i < n; i++) {
            prev[i] = (i - 1 + n) % n;
            next[i] = (i + 1) % n;
        }
        const isConvex = (a, b, c) => {
            return (px[b] - px[a]) * (py[c] - py[a]) -
                (py[b] - py[a]) * (px[c] - px[a]) > 0;
        };
        const inTri = (p, a, b, c) => {
            const x = px[p], y = py[p];
            const d1 = (x - px[b]) * (py[a] - py[b]) - (px[a] - px[b]) * (y - py[b]);
            const d2 = (x - px[c]) * (py[b] - py[c]) - (px[b] - px[c]) * (y - py[c]);
            const d3 = (x - px[a]) * (py[c] - py[a]) - (px[c] - px[a]) * (y - py[a]);
            const hasNeg = d1 < 0 || d2 < 0 || d3 < 0;
            const hasPos = d1 > 0 || d2 > 0 || d3 > 0;
            return !(hasNeg && hasPos);
        };
        const isEar = (a, b, c) => {
            if (!isConvex(a, b, c))
                return false;
            let p = next[c];
            while (p !== a) {
                if (inTri(p, a, b, c))
                    return false;
                p = next[p];
            }
            return true;
        };
        let resultLen = 0;
        let count = n;
        let i = 0;
        let stalls = 0;
        while (count > 3) {
            if (stalls > count)
                return -1;
            const p = prev[i];
            const nxt = next[i];
            if (isEar(p, i, nxt)) {
                out[outOffset + resultLen++] = p;
                out[outOffset + resultLen++] = i;
                out[outOffset + resultLen++] = nxt;
                next[p] = nxt;
                prev[nxt] = p;
                count--;
                i = nxt;
                stalls = 0;
            }
            else {
                i = next[i];
                stalls++;
            }
        }
        out[outOffset + resultLen++] = prev[i];
        out[outOffset + resultLen++] = i;
        out[outOffset + resultLen++] = next[i];
        return resultLen;
    };
    // Worklist: iterative dirty-flag scheduler. Initially queue every
    // vertex; on each successful removal, re-queue the ring neighbours so
    // chains of K=1 / K=2 vertices collapse in a single run.
    const inQueue = new Uint8Array(vertCount);
    let queue = new Int32Array(Math.max(vertCount, 16));
    let queueLen = 0;
    let queueHead = 0;
    const pushQueue = (u) => {
        if (inQueue[u])
            return;
        inQueue[u] = 1;
        if (queueLen >= queue.length) {
            const grown = new Int32Array(queue.length * 2);
            grown.set(queue);
            queue = grown;
        }
        queue[queueLen++] = u;
    };
    const compactQueue = () => {
        // Reclaim consumed prefix when slack exceeds 50% (and is large
        // enough to be worth the copy). Bounded by O(total pushes).
        if (queueHead > 4096 && queueHead * 2 > queueLen) {
            queue.copyWithin(0, queueHead, queueLen);
            queueLen -= queueHead;
            queueHead = 0;
        }
    };
    for (let v = 0; v < vertCount; v++) {
        inQueue[v] = 1;
        queue[queueLen++] = v;
    }
    // Tolerance for K=2 seam collinearity: cosine of the angle between
    // (v -> a) and (v -> b) must be <= -(1 - COLLINEAR_REL_EPS), i.e.
    // the two seam edges through v are nearly antiparallel (v lies on
    // the segment from a to b in 3D).
    const cosineMax = -1 + COLLINEAR_REL_EPS;
    // Reusable scratch for the per-arc plane descriptor.
    const arcStartIdx = new Int32Array(2);
    const arcPolySize = new Int32Array(2);
    const arcPlaneT = new Int32Array(2);
    // Reusable per-arc scratch buffers (arcCount is always 1 or 2).
    // Each slot holds the polygon vertex indices, the 2D-projected
    // coordinates, and the ear-clip triangle indices for one arc. All
    // grow monotonically to the largest polygon ever seen and are
    // reused for every worklist iteration, so the hot loop is mostly
    // allocation-free.
    const arcPolyScratch = [new Int32Array(16), new Int32Array(16)];
    const arcPxScratch = [new Float64Array(16), new Float64Array(16)];
    const arcPyScratch = [new Float64Array(16), new Float64Array(16)];
    const arcEarScratch = [new Int32Array(16), new Int32Array(16)];
    const arcEarLen = new Int32Array(2);
    const ensureArcScratch = (g, polySize) => {
        if (polySize > arcPolyScratch[g].length) {
            let c = arcPolyScratch[g].length;
            while (c < polySize)
                c *= 2;
            arcPolyScratch[g] = new Int32Array(c);
            arcPxScratch[g] = new Float64Array(c);
            arcPyScratch[g] = new Float64Array(c);
        }
        const earNeed = (polySize - 2) * 3;
        if (earNeed > arcEarScratch[g].length) {
            let c = arcEarScratch[g].length;
            while (c < earNeed)
                c *= 2;
            arcEarScratch[g] = new Int32Array(c);
        }
    };
    while (queueHead < queueLen) {
        const v = queue[queueHead++];
        inQueue[v] = 0;
        compactQueue();
        // Cheap "fan size < 3" early-out without traversing the full
        // linked list.
        const h0 = vertHead[v];
        if (h0 === -1)
            continue;
        const h1 = poolNext[h0];
        if (h1 === -1)
            continue;
        if (poolNext[h1] === -1)
            continue;
        const k = extractFan(v);
        if (k === -1)
            continue;
        const ring = fanRingScratch;
        const fanTris = fanTrisScratch;
        // Decide K. First check if all tris are coplanar with fanTris[0]
        // (K=1 fast path).
        const t0 = fanTris[0];
        const n0x = triNxArr[t0];
        const n0y = triNyArr[t0];
        const n0z = triNzArr[t0];
        const d0 = triDArr[t0];
        let allCoplanar = true;
        for (let i = 1; i < k; i++) {
            const t = fanTris[i];
            const dT = triDArr[t];
            const dotN = triNxArr[t] * n0x + triNyArr[t] * n0y + triNzArr[t] * n0z;
            if (dotN < 1 - NORMAL_EPS || Math.abs(dT - d0) > planeEps(dT, d0)) {
                allCoplanar = false;
                break;
            }
        }
        let arcCount = 0;
        if (allCoplanar) {
            // K=1: single arc covering the whole ring (k vertices).
            arcStartIdx[0] = 0;
            arcPolySize[0] = k;
            arcPlaneT[0] = t0;
            arcCount = 1;
        }
        else {
            // Walk cyclically; mark transitions where plane changes vs.
            // the previous tri in fan order. Exactly 2 transitions =>
            // K=2 candidate.
            let nTransitions = 0;
            let i1 = -1;
            let i2 = -1;
            for (let i = 0; i < k; i++) {
                const t = fanTris[i];
                const prevT = fanTris[(i - 1 + k) % k];
                const nx1 = triNxArr[t];
                const ny1 = triNyArr[t];
                const nz1 = triNzArr[t];
                const d1 = triDArr[t];
                const nx0 = triNxArr[prevT];
                const ny0 = triNyArr[prevT];
                const nz0 = triNzArr[prevT];
                const dPrev = triDArr[prevT];
                const dotN = nx1 * nx0 + ny1 * ny0 + nz1 * nz0;
                if (dotN < 1 - NORMAL_EPS || Math.abs(d1 - dPrev) > planeEps(d1, dPrev)) {
                    nTransitions++;
                    if (nTransitions === 1)
                        i1 = i;
                    else if (nTransitions === 2)
                        i2 = i;
                    else
                        break;
                }
            }
            if (nTransitions !== 2)
                continue;
            // K=2 collinearity: ring[i1], v, ring[i2] must be collinear
            // with v between (cosine of va-vb angle near -1).
            const a = ring[i1];
            const b = ring[i2];
            const ax = positions[a * 3] - positions[v * 3];
            const ay = positions[a * 3 + 1] - positions[v * 3 + 1];
            const az = positions[a * 3 + 2] - positions[v * 3 + 2];
            const bx = positions[b * 3] - positions[v * 3];
            const by = positions[b * 3 + 1] - positions[v * 3 + 1];
            const bz = positions[b * 3 + 2] - positions[v * 3 + 2];
            const lenA = Math.sqrt(ax * ax + ay * ay + az * az);
            const lenB = Math.sqrt(bx * bx + by * by + bz * bz);
            if (lenA < 1e-12 || lenB < 1e-12)
                continue;
            const cosine = (ax * bx + ay * by + az * bz) / (lenA * lenB);
            if (cosine > cosineMax)
                continue;
            // Two arcs: arc 0 covers tris[i1..i2-1] (mA tris, mA+1 polygon
            // verts ring[i1..i2]); arc 1 covers tris[i2..i1-1] cyclically
            // (mB tris, mB+1 polygon verts).
            const mA = i2 - i1;
            const mB = k - mA;
            arcStartIdx[0] = i1;
            arcPolySize[0] = mA + 1;
            arcPlaneT[0] = fanTris[i1];
            arcStartIdx[1] = i2;
            arcPolySize[1] = mB + 1;
            arcPlaneT[1] = fanTris[i2];
            arcCount = 2;
        }
        // Build polygons and triangulations into the reusable per-arc
        // scratch slots. Bail (without committing) if any arc fails to
        // triangulate.
        let allArcsOk = true;
        for (let g = 0; g < arcCount; g++) {
            const polySize = arcPolySize[g];
            const startIdx = arcStartIdx[g];
            const planeT = arcPlaneT[g];
            ensureArcScratch(g, polySize);
            const poly = arcPolyScratch[g];
            for (let j = 0; j < polySize; j++) {
                poly[j] = ring[(startIdx + j) % k];
            }
            const nx = triNxArr[planeT];
            const ny = triNyArr[planeT];
            const nz = triNzArr[planeT];
            const [tx, ty, tz, bx, by, bz] = buildBasis(nx, ny, nz);
            const px = arcPxScratch[g];
            const py = arcPyScratch[g];
            for (let j = 0; j < polySize; j++) {
                const u = poly[j];
                const x = positions[u * 3];
                const y = positions[u * 3 + 1];
                const z = positions[u * 3 + 2];
                px[j] = x * tx + y * ty + z * tz;
                py[j] = x * bx + y * by + z * bz;
            }
            const earCount = earClip(px, py, polySize, arcEarScratch[g], 0);
            if (earCount !== (polySize - 2) * 3) {
                allArcsOk = false;
                break;
            }
            arcEarLen[g] = earCount;
        }
        if (!allArcsOk)
            continue;
        // Commit: walk v's linked-list of incident tris in place. For each
        // tri, mark it dead, unlink it from each non-v vertex's list, and
        // free v's own node. Iteration is safe because we only mutate
        // OTHER vertices' lists during the walk.
        let cur = vertHead[v];
        while (cur !== -1) {
            const t = poolTri[cur];
            triAliveArr[t] = 0;
            for (let j = 0; j < 3; j++) {
                const u = triVertsArr[t * 3 + j];
                if (u === v)
                    continue;
                removeTriFromVert(u, t);
            }
            const nxt = poolNext[cur];
            freeNode(cur);
            cur = nxt;
        }
        vertHead[v] = -1;
        // Append new tris per arc, each carrying its arc's plane.
        for (let g = 0; g < arcCount; g++) {
            const planeT = arcPlaneT[g];
            const nx = triNxArr[planeT];
            const ny = triNyArr[planeT];
            const nz = triNzArr[planeT];
            const d = triDArr[planeT];
            const earIdx = arcEarScratch[g];
            const earIdxLen = arcEarLen[g];
            const poly = arcPolyScratch[g];
            for (let i = 0; i < earIdxLen; i += 3) {
                const ua = poly[earIdx[i]];
                const ub = poly[earIdx[i + 1]];
                const uc = poly[earIdx[i + 2]];
                ensureTriCap();
                const newT = triCount++;
                triVertsArr[newT * 3] = ua;
                triVertsArr[newT * 3 + 1] = ub;
                triVertsArr[newT * 3 + 2] = uc;
                triNxArr[newT] = nx;
                triNyArr[newT] = ny;
                triNzArr[newT] = nz;
                triDArr[newT] = d;
                triAliveArr[newT] = 1;
                addTriToVert(ua, newT);
                addTriToVert(ub, newT);
                addTriToVert(uc, newT);
            }
        }
        // Re-queue every ring vertex: each may now satisfy K=1 or K=2 in
        // its updated fan, allowing the collapse to propagate along long
        // collinear chains in a single sweep.
        for (let i = 0; i < k; i++) {
            pushQueue(ring[i]);
        }
    }
    // Compact: drop dead tris and unused vertices, remap indices.
    const usedVerts = new Uint8Array(vertCount);
    let outTriCount = 0;
    for (let t = 0; t < triCount; t++) {
        if (triAliveArr[t] === 0)
            continue;
        outTriCount++;
        usedVerts[triVertsArr[t * 3]] = 1;
        usedVerts[triVertsArr[t * 3 + 1]] = 1;
        usedVerts[triVertsArr[t * 3 + 2]] = 1;
    }
    let outVertCount = 0;
    const vertRemap = new Int32Array(vertCount);
    for (let v = 0; v < vertCount; v++) {
        if (usedVerts[v] === 1) {
            vertRemap[v] = outVertCount++;
        }
        else {
            vertRemap[v] = -1;
        }
    }
    const outPositions = new Float32Array(outVertCount * 3);
    for (let v = 0; v < vertCount; v++) {
        if (usedVerts[v] === 0)
            continue;
        const o = vertRemap[v] * 3;
        outPositions[o] = positions[v * 3];
        outPositions[o + 1] = positions[v * 3 + 1];
        outPositions[o + 2] = positions[v * 3 + 2];
    }
    const outIndices = new Uint32Array(outTriCount * 3);
    let oi = 0;
    for (let t = 0; t < triCount; t++) {
        if (triAliveArr[t] === 0)
            continue;
        outIndices[oi++] = vertRemap[triVertsArr[t * 3]];
        outIndices[oi++] = vertRemap[triVertsArr[t * 3 + 1]];
        outIndices[oi++] = vertRemap[triVertsArr[t * 3 + 2]];
    }
    return { positions: outPositions, indices: outIndices };
};

/**
 * Build a minimal GLB (glTF 2.0 binary) file containing a single triangle mesh.
 *
 * The output contains only positions and triangle indices — no normals,
 * UVs, or materials — suitable for collision meshes.
 *
 * @param positions - Vertex positions (3 floats per vertex)
 * @param indices - Triangle indices (3 per triangle, unsigned 32-bit)
 * @returns GLB file as a Uint8Array
 */
function encodeGlb(positions, indices) {
    const vertexCount = positions.length / 3;
    const indexCount = indices.length;
    let minX = Infinity, minY = Infinity, minZ = Infinity;
    let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    for (let i = 0; i < positions.length; i += 3) {
        const x = positions[i], y = positions[i + 1], z = positions[i + 2];
        if (x < minX)
            minX = x;
        if (y < minY)
            minY = y;
        if (z < minZ)
            minZ = z;
        if (x > maxX)
            maxX = x;
        if (y > maxY)
            maxY = y;
        if (z > maxZ)
            maxZ = z;
    }
    const positionsByteLength = positions.byteLength;
    const indicesByteLength = indices.byteLength;
    const totalBinSize = positionsByteLength + indicesByteLength;
    const gltf = {
        asset: { version: '2.0', generator: 'splat-transform' },
        scene: 0,
        scenes: [{ nodes: [0] }],
        nodes: [{ mesh: 0 }],
        meshes: [{
                primitives: [{
                        attributes: { POSITION: 0 },
                        indices: 1
                    }]
            }],
        accessors: [
            {
                bufferView: 0,
                componentType: 5126, // FLOAT
                count: vertexCount,
                type: 'VEC3',
                min: [minX, minY, minZ],
                max: [maxX, maxY, maxZ]
            },
            {
                bufferView: 1,
                componentType: 5125, // UNSIGNED_INT
                count: indexCount,
                type: 'SCALAR'
            }
        ],
        bufferViews: [
            {
                buffer: 0,
                byteOffset: 0,
                byteLength: positionsByteLength,
                target: 34962 // ARRAY_BUFFER
            },
            {
                buffer: 0,
                byteOffset: positionsByteLength,
                byteLength: indicesByteLength,
                target: 34963 // ELEMENT_ARRAY_BUFFER
            }
        ],
        buffers: [{ byteLength: totalBinSize }]
    };
    const jsonString = JSON.stringify(gltf);
    const jsonEncoder = new TextEncoder();
    const jsonBytes = jsonEncoder.encode(jsonString);
    // JSON chunk must be padded to 4-byte alignment with spaces (0x20)
    const jsonPadding = (4 - (jsonBytes.length % 4)) % 4;
    const jsonChunkLength = jsonBytes.length + jsonPadding;
    // BIN chunk must be padded to 4-byte alignment with zeros
    const binPadding = (4 - (totalBinSize % 4)) % 4;
    const binChunkLength = totalBinSize + binPadding;
    // GLB layout: header (12) + JSON chunk header (8) + JSON data + BIN chunk header (8) + BIN data
    const totalLength = 12 + 8 + jsonChunkLength + 8 + binChunkLength;
    const buffer = new ArrayBuffer(totalLength);
    const view = new DataView(buffer);
    const byteArray = new Uint8Array(buffer);
    let offset = 0;
    // GLB header
    view.setUint32(offset, 0x46546C67, true);
    offset += 4; // magic: "glTF"
    view.setUint32(offset, 2, true);
    offset += 4; // version: 2
    view.setUint32(offset, totalLength, true);
    offset += 4; // total length
    // JSON chunk header
    view.setUint32(offset, jsonChunkLength, true);
    offset += 4;
    view.setUint32(offset, 0x4E4F534A, true);
    offset += 4; // type: "JSON"
    // JSON chunk data
    byteArray.set(jsonBytes, offset);
    offset += jsonBytes.length;
    for (let i = 0; i < jsonPadding; i++) {
        byteArray[offset++] = 0x20;
    }
    // BIN chunk header
    view.setUint32(offset, binChunkLength, true);
    offset += 4;
    view.setUint32(offset, 0x004E4942, true);
    offset += 4; // type: "BIN\0"
    // BIN chunk data: positions then indices
    byteArray.set(new Uint8Array(positions.buffer, positions.byteOffset, positionsByteLength), offset);
    offset += positionsByteLength;
    byteArray.set(new Uint8Array(indices.buffer, indices.byteOffset, indicesByteLength), offset);
    return byteArray;
}
/**
 * Extract a collision mesh from voxel data and encode it as a GLB file.
 *
 * Runs marching cubes on the voxel surface, then a lossless coplanar-merge
 * pass that fuses the redundant axis-aligned triangles inside each
 * voxel-face plane into greedy-style quads while leaving the corner-cutting
 * bevel triangles untouched. The output surface is identical to the raw MC
 * surface but typically has 1-2 orders of magnitude fewer triangles.
 *
 * @param blockBuffer - Voxel block data after filtering
 * @param gridBounds - Grid bounds aligned to block boundaries
 * @param voxelResolution - Size of each voxel in world units
 * @returns GLB bytes, or null if no triangles were generated
 */
const buildCollisionMesh = (blockBuffer, gridBounds, voxelResolution) => {
    const g = logger.group('Collision mesh');
    const extractSub = logger.group('Extracting');
    const rawMesh = marchingCubes(blockBuffer, gridBounds, voxelResolution);
    logger.info(`raw vertices: ${fmtCount(rawMesh.positions.length / 3)}`);
    logger.info(`raw triangles: ${fmtCount(rawMesh.indices.length / 3)}`);
    if (rawMesh.indices.length < 3) {
        logger.warn('no triangles generated, skipping GLB output');
        extractSub.end();
        g.end();
        return null;
    }
    extractSub.end();
    const mergeSub = logger.group('Merging coplanar faces');
    const finalMesh = coplanarMerge(rawMesh, voxelResolution);
    const reduction = (1 - finalMesh.indices.length / rawMesh.indices.length) * 100;
    logger.info(`merged vertices: ${fmtCount(finalMesh.positions.length / 3)}`);
    logger.info(`merged triangles: ${fmtCount(finalMesh.indices.length / 3)}`);
    logger.info(`reduction: ${reduction.toFixed(0)}%`);
    mergeSub.end();
    g.end();
    return encodeGlb(finalMesh.positions, finalMesh.indices);
};

/**
 * Solid leaf node marker: childMask = 0xFF, baseOffset = 0.
 * This is unambiguous because BFS layout guarantees children always come after
 * their parent, so baseOffset = 0 is never valid for an interior node.
 */
const SOLID_LEAF_MARKER = 0xFF000000 >>> 0;
// ============================================================================
// Octree Construction
// ============================================================================
/**
 * Build a sparse octree from accumulated voxelization blocks.
 *
 * Uses Structure-of-Arrays (SoA) representation and linear scans on sorted
 * Morton codes instead of Maps and per-node objects for performance.
 *
 * @param buffer - BlockMaskBuffer containing voxelized blocks
 * @param gridBounds - Grid bounds aligned to block boundaries
 * @param sceneBounds - Original scene bounds
 * @param voxelResolution - Size of each voxel in world units
 * @returns Sparse octree structure
 */
function buildSparseOctree(buffer, gridBounds, sceneBounds, voxelResolution) {
    performance.now();
    const mixed = buffer.getMixedBlocks();
    const solid = buffer.getSolidBlocks();
    const totalBlocks = mixed.morton.length + solid.length;
    // --- Phase 1: Combine blocks into SoA arrays and sort by Morton code ---
    // Uses typed arrays to reduce per-element memory overhead. The block scope
    // allows the unsorted intermediates (mortons, types, maskIndices, sortOrder)
    // to be GC'd before Phase 2 begins.
    let sortedMortons;
    let sortedTypes;
    let sortedMaskIndices;
    {
        const mortons = new Float64Array(totalBlocks);
        const types = new Uint8Array(totalBlocks);
        const maskIndices = new Int32Array(totalBlocks);
        let idx = 0;
        for (let i = 0; i < mixed.morton.length; i++) {
            mortons[idx] = mixed.morton[i];
            types[idx] = 2 /* BlockType.Mixed */;
            maskIndices[idx] = i;
            idx++;
        }
        for (let i = 0; i < solid.length; i++) {
            mortons[idx] = solid[i];
            types[idx] = 1 /* BlockType.Solid */;
            maskIndices[idx] = -1;
            idx++;
        }
        const sortOrder = new Uint32Array(totalBlocks);
        for (let i = 0; i < totalBlocks; i++)
            sortOrder[i] = i;
        sortOrder.sort((a, b) => mortons[a] - mortons[b]);
        sortedMortons = new Float64Array(totalBlocks);
        sortedTypes = new Uint8Array(totalBlocks);
        sortedMaskIndices = new Int32Array(totalBlocks);
        for (let i = 0; i < totalBlocks; i++) {
            const si = sortOrder[i];
            sortedMortons[i] = mortons[si];
            sortedTypes[i] = types[si];
            sortedMaskIndices[i] = maskIndices[si];
        }
    }
    performance.now();
    // --- Phase 2: Build tree bottom-up level by level using linear scan ---
    // Instead of Map<number, BuildNode> per level, we use sorted parallel
    // arrays and exploit the fact that sorted Morton codes make parent
    // grouping a simple linear scan (consecutive entries with the same
    // floor(morton/8) share a parent).
    const bar = logger.bar('Building tree', 10);
    let octreeStep = 0;
    // Calculate tree depth based on grid size
    const gridSize = new Vec3(gridBounds.max.x - gridBounds.min.x, gridBounds.max.y - gridBounds.min.y, gridBounds.max.z - gridBounds.min.z);
    const blockSize = voxelResolution * 4;
    const blocksPerAxis = Math.max(Math.ceil(gridSize.x / blockSize), Math.ceil(gridSize.y / blockSize), Math.ceil(gridSize.z / blockSize));
    const treeDepth = Math.max(1, Math.ceil(Math.log2(blocksPerAxis)));
    // Store level data for each tree level (level 0 = leaves, higher = toward root)
    const levels = [];
    // Current level data starts as the sorted leaf blocks
    let curMortons = sortedMortons;
    let curTypes = sortedTypes;
    let curMaskIndices = sortedMaskIndices;
    let curChildMasks = null;
    // 1 step for init
    bar.tick();
    octreeStep++;
    // Build up level by level
    let actualDepth = treeDepth;
    const levelSteps = 8;
    for (let level = 0; level < treeDepth; level++) {
        // Report inner progress scaled to levelSteps
        const targetStep = 1 + Math.min(levelSteps, Math.floor((level + 1) / treeDepth * levelSteps));
        while (octreeStep < targetStep) {
            bar.tick();
            octreeStep++;
        }
        // Save current level before building the next one above
        levels.push({
            mortons: curMortons,
            types: curTypes,
            maskIndices: curMaskIndices,
            childMasks: curChildMasks
        });
        // Build next level using linear scan on sorted data.
        // Since curMortons is sorted, entries sharing the same parent
        // (floor(morton/8)) are contiguous — no Map needed.
        const n = curMortons.length;
        const nextMortons = [];
        const nextTypes = [];
        const nextMaskIndices = [];
        const nextChildMasks = [];
        let i = 0;
        while (i < n) {
            const parentMorton = Math.floor(curMortons[i] / 8);
            let childMask = 0;
            let allSolid = true;
            let childCount = 0;
            // Scan all consecutive entries that share this parent
            while (i < n && Math.floor(curMortons[i] / 8) === parentMorton) {
                const octant = curMortons[i] % 8;
                childMask |= (1 << octant);
                if (curTypes[i] !== 1 /* BlockType.Solid */) {
                    allSolid = false;
                }
                childCount++;
                i++;
            }
            if (allSolid && childCount === 8) {
                // All 8 children are solid — collapse to solid parent
                nextMortons.push(parentMorton);
                nextTypes.push(1 /* BlockType.Solid */);
                nextMaskIndices.push(-1);
                nextChildMasks.push(0);
            }
            else {
                // Interior node with sparse children
                nextMortons.push(parentMorton);
                nextTypes.push(2 /* BlockType.Mixed */);
                nextMaskIndices.push(-1);
                nextChildMasks.push(childMask);
            }
        }
        curMortons = nextMortons;
        curTypes = nextTypes;
        curMaskIndices = nextMaskIndices;
        curChildMasks = nextChildMasks;
        // Break when the tree is empty or has converged to a single root at Morton 0.
        // We must NOT break early if the single remaining node has a non-zero Morton,
        // because the reader reconstructs Morton codes starting from root Morton 0.
        if (curMortons.length === 0 ||
            (curMortons.length === 1 && curMortons[0] === 0)) {
            actualDepth = level + 1;
            break;
        }
    }
    // Save the root level
    levels.push({
        mortons: curMortons,
        types: curTypes,
        maskIndices: curMaskIndices,
        childMasks: curChildMasks
    });
    // Flush remaining level steps
    while (octreeStep < 9) {
        bar.tick();
        octreeStep++;
    }
    performance.now();
    // --- Phase 3: Flatten tree to Laine-Karras format ---
    // Uses wave-based BFS on level arrays, avoiding BuildNode objects
    // and the O(n²) queue.shift() of the original approach.
    const result = flattenTreeFromLevels(levels, mixed.masks, gridBounds, sceneBounds, voxelResolution, actualDepth);
    performance.now();
    // Final step (10th)
    bar.tick();
    bar.end();
    return result;
}
/**
 * Flatten the level-based tree into Laine-Karras format arrays using
 * wave-based BFS traversal from root down through levels.
 *
 * Uses parallel arrays for BFS waves (no per-node object allocation)
 * and binary search on sorted level mortons to locate children.
 *
 * @param levels - Array of per-level SoA data (index 0 = leaves, last = root).
 * @param mixedMasks - Interleaved voxel masks for mixed leaf blocks.
 * @param gridBounds - Grid bounds aligned to block boundaries.
 * @param sceneBounds - Original Gaussian scene bounds.
 * @param voxelResolution - Size of each voxel in world units.
 * @param treeDepth - Maximum tree depth.
 * @returns Sparse octree structure in Laine-Karras format.
 */
function flattenTreeFromLevels(levels, mixedMasks, gridBounds, sceneBounds, voxelResolution, treeDepth) {
    const rootLevel = levels[levels.length - 1];
    if (rootLevel.mortons.length === 0) {
        // Empty tree
        return {
            gridBounds,
            sceneBounds,
            voxelResolution,
            leafSize: 4,
            treeDepth,
            numInteriorNodes: 0,
            numMixedLeaves: 0,
            nodes: new Uint32Array(0),
            leafData: new Uint32Array(0)
        };
    }
    // Upper bound on total nodes (not all may be reachable if solids collapsed)
    let maxNodes = 0;
    for (let l = 0; l < levels.length; l++) {
        maxNodes += levels[l].mortons.length;
    }
    const nodes = new Uint32Array(maxNodes);
    const leafDataList = [];
    let numInteriorNodes = 0;
    let numMixedLeaves = 0;
    let emitPos = 0;
    // BFS wave as parallel arrays (avoids object allocation per queue entry)
    let waveLi = [];
    let waveIi = [];
    // Initialize wave with root level entries
    const rootLi = levels.length - 1;
    for (let i = 0; i < rootLevel.mortons.length; i++) {
        waveLi.push(rootLi);
        waveIi.push(i);
    }
    // Reusable arrays for tracking interior nodes within each wave
    const intPos = [];
    const intLi = [];
    const intIi = [];
    const intMask = [];
    while (waveLi.length > 0) {
        // Clear interior tracking arrays
        intPos.length = 0;
        intLi.length = 0;
        intIi.length = 0;
        intMask.length = 0;
        // Emit all nodes in this wave
        for (let w = 0; w < waveLi.length; w++) {
            const li = waveLi[w];
            const ii = waveIi[w];
            const level = levels[li];
            const type = level.types[ii];
            // A node is a leaf if it's Solid (at any level, collapsed or original)
            // or if it's at level 0 (the leaf block level).
            const isLeaf = (type === 1 /* BlockType.Solid */) || (li === 0);
            if (isLeaf) {
                if (type === 1 /* BlockType.Solid */) {
                    nodes[emitPos] = SOLID_LEAF_MARKER;
                }
                else {
                    // Mixed leaf — store index into leafData
                    const maskIdx = level.maskIndices[ii];
                    const leafDataIndex = leafDataList.length >> 1;
                    leafDataList.push(mixedMasks[maskIdx * 2]);
                    leafDataList.push(mixedMasks[maskIdx * 2 + 1]);
                    nodes[emitPos] = leafDataIndex & 0x00FFFFFF;
                    numMixedLeaves++;
                }
            }
            else {
                // Interior node — record position for backfill after wave
                intPos.push(emitPos);
                intLi.push(li);
                intIi.push(ii);
                intMask.push(level.childMasks[ii]);
                numInteriorNodes++;
                // Placeholder (will be filled below)
                nodes[emitPos] = 0;
            }
            emitPos++;
        }
        // Build next wave from children of interior nodes.
        // Backfill interior node encodings with correct baseOffset.
        const nextWaveLi = [];
        const nextWaveIi = [];
        let nextChildStart = emitPos;
        for (let j = 0; j < intPos.length; j++) {
            const childMask = intMask[j];
            const childCount = popcount(childMask);
            // Encode interior node: mask in high byte, baseOffset in low 24 bits
            nodes[intPos[j]] = ((childMask & 0xFF) << 24) | (nextChildStart & 0x00FFFFFF);
            // Find children in the level below using binary search.
            // Since each level's mortons are sorted, this is O(log n) per lookup.
            const childLi = intLi[j] - 1;
            const childLevel = levels[childLi];
            const myMorton = levels[intLi[j]].mortons[intIi[j]];
            const childMortonBase = myMorton * 8;
            const childMortonEnd = childMortonBase + 8;
            const childMortons = childLevel.mortons;
            // Binary search for first child with morton >= childMortonBase
            let lo = 0;
            let hi = childMortons.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (childMortons[mid] < childMortonBase)
                    lo = mid + 1;
                else
                    hi = mid;
            }
            // Collect all children in morton order (they are contiguous in sorted array)
            while (lo < childMortons.length && childMortons[lo] < childMortonEnd) {
                nextWaveLi.push(childLi);
                nextWaveIi.push(lo);
                lo++;
            }
            nextChildStart += childCount;
        }
        waveLi = nextWaveLi;
        waveIi = nextWaveIi;
    }
    return {
        gridBounds,
        sceneBounds,
        voxelResolution,
        leafSize: 4,
        treeDepth,
        numInteriorNodes,
        numMixedLeaves,
        nodes: emitPos === maxNodes ? nodes : nodes.slice(0, emitPos),
        leafData: new Uint32Array(leafDataList)
    };
}

/**
 * Append-only buffer for streaming voxelization results.
 * Stores block masks using Morton codes for efficient octree construction.
 */
class BlockMaskBuffer {
    /** Morton codes for mixed blocks */
    _mixedMorton = [];
    /** Interleaved voxel masks for mixed blocks: [lo0, hi0, lo1, hi1, ...] */
    _mixedMasks = [];
    /** Morton codes for solid blocks (mask is implicitly all 1s) */
    _solidMorton = [];
    /**
     * Add a non-empty block to the buffer.
     * Automatically classifies as solid or mixed based on mask values.
     *
     * @param morton - Morton code encoding block position
     * @param lo - Lower 32 bits of voxel mask
     * @param hi - Upper 32 bits of voxel mask
     */
    addBlock(morton, lo, hi) {
        if (isEmpty(lo, hi)) {
            return;
        }
        if (isSolid(lo, hi)) {
            this._solidMorton.push(morton);
        }
        else {
            this._mixedMorton.push(morton);
            this._mixedMasks.push(lo, hi);
        }
    }
    /**
     * Get all mixed blocks.
     *
     * @returns Object with morton codes and interleaved masks
     */
    getMixedBlocks() {
        return {
            morton: this._mixedMorton,
            masks: this._mixedMasks
        };
    }
    /**
     * Get all solid blocks.
     *
     * @returns Array of Morton codes
     */
    getSolidBlocks() {
        return this._solidMorton;
    }
    /**
     * Get total number of blocks stored.
     *
     * @returns Count of mixed + solid blocks
     */
    get count() {
        return this._mixedMorton.length + this._solidMorton.length;
    }
    /**
     * Get number of mixed blocks.
     *
     * @returns Count of mixed blocks
     */
    get mixedCount() {
        return this._mixedMorton.length;
    }
    /**
     * Get number of solid blocks.
     *
     * @returns Count of solid blocks
     */
    get solidCount() {
        return this._solidMorton.length;
    }
    /**
     * Clear all buffered blocks.
     */
    clear() {
        this._mixedMorton.length = 0;
        this._mixedMasks.length = 0;
        this._solidMorton.length = 0;
    }
}

// ============================================================================
// Edge mask constants for 4x4x4 voxel blocks
// ============================================================================
// Bit layout: bitIdx = lx + ly*4 + lz*16
// lo = bits 0-31 (lz=0: 0-15, lz=1: 16-31)
// hi = bits 32-63 (lz=2: 0-15, lz=3: 16-31)
/** lx=0 positions in each 32-bit word */
const FACE_X0 = 0x11111111;
/** lx=3 positions in each 32-bit word */
const FACE_X3 = 0x88888888;
/** ly=0 positions in each 32-bit word */
const FACE_Y0 = 0x000F000F;
/** ly=3 positions in each 32-bit word */
const FACE_Y3 = 0xF000F000;
/** lz=0 positions: lo bits 0-15 */
const FACE_Z0_LO = 0x0000FFFF;
/** lz=3 positions: hi bits 16-31 */
const FACE_Z3_HI = 0xFFFF0000 >>> 0;
const SOLID_MASK = 0xFFFFFFFF >>> 0;
// ============================================================================
// Main function
// ============================================================================
/**
 * Remove isolated voxels and fill isolated empty voxels within mixed blocks.
 *
 * For each mixed block, computes 6 per-direction occupancy masks (in-block via
 * bit shifts + cross-block via adjacent block lookups), then:
 *   - Remove: keeps only voxels with at least one occupied 6-connected neighbor
 *   - Fill: fills empty voxels where all 6 neighbors are occupied
 *
 * Blocks that become empty or solid as a consequence are handled automatically.
 *
 * @param buffer - BlockMaskBuffer with voxelization results
 * @returns New BlockMaskBuffer with filtered/filled data
 */
function filterAndFillBlocks(buffer) {
    const mixed = buffer.getMixedBlocks();
    const solid = buffer.getSolidBlocks();
    const masks = mixed.masks;
    // Build lookup structures from original (unmodified) data
    const solidSet = new Set();
    for (let i = 0; i < solid.length; i++) {
        solidSet.add(solid[i]);
    }
    const mixedMap = new Map();
    for (let i = 0; i < mixed.morton.length; i++) {
        mixedMap.set(mixed.morton[i], i);
    }
    // New masks array (snapshot: cross-block lookups always read the original masks)
    const newMasks = new Array(masks.length);
    let voxelsRemoved = 0;
    let voxelsFilled = 0;
    for (let i = 0; i < mixed.morton.length; i++) {
        const morton = mixed.morton[i];
        const origLo = masks[i * 2];
        const origHi = masks[i * 2 + 1];
        const [bx, by, bz] = mortonToXYZ(morton);
        // --- In-block per-direction occupancy masks ---
        // +X: result[p] = mask[p+1], valid for lx < 3
        let pxLo = (origLo >>> 1) & ~FACE_X3;
        let pxHi = (origHi >>> 1) & ~FACE_X3;
        // -X: result[p] = mask[p-1], valid for lx > 0
        let mxLo = (origLo << 1) & ~FACE_X0;
        let mxHi = (origHi << 1) & ~FACE_X0;
        // +Y: result[p] = mask[p+4], valid for ly < 3
        let pyLo = (origLo >>> 4) & ~FACE_Y3;
        let pyHi = (origHi >>> 4) & ~FACE_Y3;
        // -Y: result[p] = mask[p-4], valid for ly > 0
        let myLo = (origLo << 4) & ~FACE_Y0;
        let myHi = (origHi << 4) & ~FACE_Y0;
        // +Z: result[p] = mask[p+16], crosses lo/hi at lz=1->lz=2
        let pzLo = (origLo >>> 16) | (origHi << 16);
        let pzHi = origHi >>> 16;
        // -Z: result[p] = mask[p-16], crosses lo/hi at lz=2->lz=1
        let mzLo = origLo << 16;
        let mzHi = (origHi << 16) | (origLo >>> 16);
        // --- Cross-block contributions ---
        // +X: our lx=3 face <- adjacent's lx=0 face (shifted left by 3)
        addCrossFace(bx + 1, by, bz, solidSet, mixedMap, masks, FACE_X3, FACE_X0, 3, true, pxLo, pxHi, (lo, hi) => {
            pxLo = lo;
            pxHi = hi;
        });
        // -X: our lx=0 face <- adjacent's lx=3 face (shifted right by 3)
        addCrossFace(bx - 1, by, bz, solidSet, mixedMap, masks, FACE_X0, FACE_X3, 3, false, mxLo, mxHi, (lo, hi) => {
            mxLo = lo;
            mxHi = hi;
        });
        // +Y: our ly=3 face <- adjacent's ly=0 face (shifted left by 12)
        addCrossFace(bx, by + 1, bz, solidSet, mixedMap, masks, FACE_Y3, FACE_Y0, 12, true, pyLo, pyHi, (lo, hi) => {
            pyLo = lo;
            pyHi = hi;
        });
        // -Y: our ly=0 face <- adjacent's ly=3 face (shifted right by 12)
        addCrossFace(bx, by - 1, bz, solidSet, mixedMap, masks, FACE_Y0, FACE_Y3, 12, false, myLo, myHi, (lo, hi) => {
            myLo = lo;
            myHi = hi;
        });
        // +Z: our lz=3 face (hi bits 16-31) <- adjacent's lz=0 face (lo bits 0-15)
        addCrossFaceZ(bx, by, bz + 1, solidSet, mixedMap, masks, true, pzLo, pzHi, (lo, hi) => {
            pzLo = lo;
            pzHi = hi;
        });
        // -Z: our lz=0 face (lo bits 0-15) <- adjacent's lz=3 face (hi bits 16-31)
        addCrossFaceZ(bx, by, bz - 1, solidSet, mixedMap, masks, false, mzLo, mzHi, (lo, hi) => {
            mzLo = lo;
            mzHi = hi;
        });
        // --- Apply operations ---
        // Remove isolated voxels: keep only those with at least one occupied neighbor
        const neighborLo = pxLo | mxLo | pyLo | myLo | pzLo | mzLo;
        const neighborHi = pxHi | mxHi | pyHi | myHi | pzHi | mzHi;
        let lo = origLo & neighborLo;
        let hi = origHi & neighborHi;
        // Fill isolated empties: fill where all 6 neighbors are occupied
        const fillLo = ~lo & pxLo & mxLo & pyLo & myLo & pzLo & mzLo;
        const fillHi = ~hi & pxHi & mxHi & pyHi & myHi & pzHi & mzHi;
        lo |= fillLo;
        hi |= fillHi;
        voxelsRemoved += popcount(origLo & ~lo) + popcount(origHi & ~hi);
        voxelsFilled += popcount(lo & ~origLo) + popcount(hi & ~origHi);
        newMasks[i * 2] = lo;
        newMasks[i * 2 + 1] = hi;
    }
    // Rebuild buffer with state transitions (mixed->empty, mixed->solid)
    const result = new BlockMaskBuffer();
    for (let i = 0; i < mixed.morton.length; i++) {
        const lo = newMasks[i * 2];
        const hi = newMasks[i * 2 + 1];
        result.addBlock(mixed.morton[i], lo, hi);
    }
    for (let i = 0; i < solid.length; i++) {
        result.addBlock(solid[i], SOLID_MASK, SOLID_MASK);
    }
    logger.debug(`block cleanup: ${voxelsRemoved} voxels removed, ${voxelsFilled} voxels filled`);
    return result;
}
// ============================================================================
// Cross-block face helpers
// ============================================================================
function addCrossFace(nx, ny, nz, solidSet, mixedMap, masks, ourFaceMask, adjFaceMask, shiftAmount, shiftLeft, curLo, curHi, write) {
    const adjMorton = xyzToMorton(nx, ny, nz);
    if (solidSet.has(adjMorton)) {
        write(curLo | ourFaceMask, curHi | ourFaceMask);
        return;
    }
    const adjIdx = mixedMap.get(adjMorton);
    if (adjIdx === undefined) {
        write(curLo, curHi);
        return;
    }
    const adjLo = masks[adjIdx * 2];
    const adjHi = masks[adjIdx * 2 + 1];
    const faceLo = adjLo & adjFaceMask;
    const faceHi = adjHi & adjFaceMask;
    if (shiftLeft) {
        write(curLo | (faceLo << shiftAmount), curHi | (faceHi << shiftAmount));
    }
    else {
        write(curLo | (faceLo >>> shiftAmount), curHi | (faceHi >>> shiftAmount));
    }
}
function addCrossFaceZ(nx, ny, nz, solidSet, mixedMap, masks, plusZ, curLo, curHi, write) {
    const adjMorton = xyzToMorton(nx, ny, nz);
    if (solidSet.has(adjMorton)) {
        if (plusZ) {
            write(curLo, curHi | FACE_Z3_HI);
        }
        else {
            write(curLo | FACE_Z0_LO, curHi);
        }
        return;
    }
    const adjIdx = mixedMap.get(adjMorton);
    if (adjIdx === undefined) {
        write(curLo, curHi);
        return;
    }
    const adjLo = masks[adjIdx * 2];
    const adjHi = masks[adjIdx * 2 + 1];
    if (plusZ) {
        write(curLo, curHi | ((adjLo & FACE_Z0_LO) << 16));
    }
    else {
        write(curLo | ((adjHi & FACE_Z3_HI) >>> 16), curHi);
    }
}

/**
 * GPU-accelerated voxelization of Gaussian splat data into a block mask buffer.
 *
 * Uses double-buffered pipelining: the CPU prepares the next mega-dispatch
 * (BVH queries + index copying) while the GPU executes the current one.
 *
 * @param bvh - Gaussian bounding volume hierarchy for spatial queries.
 * @param gpuVoxelization - GPU voxelization pipeline with Gaussians already uploaded.
 * @param gridBounds - Block-aligned grid bounds to voxelize within.
 * @param voxelResolution - Size of each voxel in world units.
 * @param opacityCutoff - Opacity threshold for solid voxels.
 * @returns Block mask buffer containing voxelization results.
 */
const voxelizeToBuffer = async (bvh, gpuVoxelization, gridBounds, voxelResolution, opacityCutoff) => {
    const blockSize = 4 * voxelResolution;
    const numBlocksX = Math.round((gridBounds.max.x - gridBounds.min.x) / blockSize);
    const numBlocksY = Math.round((gridBounds.max.y - gridBounds.min.y) / blockSize);
    const numBlocksZ = Math.round((gridBounds.max.z - gridBounds.min.z) / blockSize);
    const buffer = new BlockMaskBuffer();
    const batchSize = 16;
    const MEGA_MAX_BATCHES = 512;
    const MEGA_MAX_INDICES = 4 * 1024 * 1024;
    const maxBlocks = GpuVoxelization.MAX_BLOCKS_PER_BATCH;
    const numSlots = GpuVoxelization.NUM_SLOTS;
    const slotIndexArrays = [];
    const slotCapacities = [];
    for (let i = 0; i < numSlots; i++) {
        slotCapacities.push(1024 * 1024);
        slotIndexArrays.push(new Uint32Array(1024 * 1024));
    }
    let currentSlot = 0;
    let indexOffset = 0;
    const pendingBatches = [];
    let inflight = null;
    const processResults = (masks, batches) => {
        for (let b = 0; b < batches.length; b++) {
            const batch = batches[b];
            const batchResultOffset = b * maxBlocks * 2;
            const totalBatchBlocks = batch.numBlocksX * batch.numBlocksY * batch.numBlocksZ;
            for (let blockIdx = 0; blockIdx < totalBatchBlocks; blockIdx++) {
                const maskLo = masks[batchResultOffset + blockIdx * 2];
                const maskHi = masks[batchResultOffset + blockIdx * 2 + 1];
                if (maskLo === 0 && maskHi === 0)
                    continue;
                const localX = blockIdx % batch.numBlocksX;
                const localY = (blockIdx / batch.numBlocksX | 0) % batch.numBlocksY;
                const localZ = (blockIdx / (batch.numBlocksX * batch.numBlocksY)) | 0;
                const absBlockX = batch.bx + localX;
                const absBlockY = batch.by + localY;
                const absBlockZ = batch.bz + localZ;
                const morton = xyzToMorton(absBlockX, absBlockY, absBlockZ);
                buffer.addBlock(morton, maskLo, maskHi);
            }
        }
    };
    const flushPendingBatches = async () => {
        if (pendingBatches.length === 0)
            return;
        const batchesToSubmit = pendingBatches.slice();
        const submitSlot = currentSlot;
        const submitIndexArray = slotIndexArrays[submitSlot];
        const submitIndexCount = indexOffset;
        currentSlot = (currentSlot + 1) % numSlots;
        pendingBatches.length = 0;
        indexOffset = 0;
        const resultPromise = gpuVoxelization.submitMultiBatch(submitSlot, submitIndexArray, submitIndexCount, batchesToSubmit, voxelResolution, opacityCutoff);
        if (inflight) {
            const result = await inflight.resultPromise;
            processResults(result.masks, inflight.batches);
        }
        inflight = { resultPromise, batches: batchesToSubmit };
    };
    const numZBatches = Math.max(1, Math.ceil(numBlocksZ / batchSize));
    const bar = logger.bar('Voxelizing', numZBatches);
    for (let bz = 0; bz < numBlocksZ; bz += batchSize) {
        for (let by = 0; by < numBlocksY; by += batchSize) {
            for (let bx = 0; bx < numBlocksX; bx += batchSize) {
                const currBatchX = Math.min(batchSize, numBlocksX - bx);
                const currBatchY = Math.min(batchSize, numBlocksY - by);
                const currBatchZ = Math.min(batchSize, numBlocksZ - bz);
                const blockMinX = gridBounds.min.x + bx * blockSize;
                const blockMinY = gridBounds.min.y + by * blockSize;
                const blockMinZ = gridBounds.min.z + bz * blockSize;
                const blockMaxX = blockMinX + currBatchX * blockSize;
                const blockMaxY = blockMinY + currBatchY * blockSize;
                const blockMaxZ = blockMinZ + currBatchZ * blockSize;
                const overlapping = bvh.queryOverlappingRaw(blockMinX, blockMinY, blockMinZ, blockMaxX, blockMaxY, blockMaxZ);
                if (overlapping.length === 0) {
                    continue;
                }
                const needed = indexOffset + overlapping.length;
                if (needed > slotCapacities[currentSlot]) {
                    slotCapacities[currentSlot] = Math.max(slotCapacities[currentSlot] * 2, needed);
                    const newArray = new Uint32Array(slotCapacities[currentSlot]);
                    newArray.set(slotIndexArrays[currentSlot].subarray(0, indexOffset));
                    slotIndexArrays[currentSlot] = newArray;
                }
                slotIndexArrays[currentSlot].set(overlapping, indexOffset);
                pendingBatches.push({
                    indexOffset,
                    indexCount: overlapping.length,
                    blockMin: { x: blockMinX, y: blockMinY, z: blockMinZ },
                    numBlocksX: currBatchX,
                    numBlocksY: currBatchY,
                    numBlocksZ: currBatchZ,
                    bx,
                    by,
                    bz
                });
                indexOffset += overlapping.length;
                if (pendingBatches.length >= MEGA_MAX_BATCHES || indexOffset >= MEGA_MAX_INDICES) {
                    await flushPendingBatches();
                }
            }
        }
        await flushPendingBatches();
        bar.tick();
    }
    if (inflight) {
        const result = await inflight.resultPromise;
        processResults(result.masks, inflight.batches);
        inflight = null;
    }
    bar.end();
    return buffer;
};
/**
 * Align bounds to 4x4x4 block boundaries.
 *
 * @param minX - Scene minimum X
 * @param minY - Scene minimum Y
 * @param minZ - Scene minimum Z
 * @param maxX - Scene maximum X
 * @param maxY - Scene maximum Y
 * @param maxZ - Scene maximum Z
 * @param voxelResolution - Size of each voxel
 * @returns Aligned bounds
 */
function alignGridBounds(minX, minY, minZ, maxX, maxY, maxZ, voxelResolution) {
    const blockSize = 4 * voxelResolution;
    return {
        min: new Vec3(Math.floor(minX / blockSize) * blockSize, Math.floor(minY / blockSize) * blockSize, Math.floor(minZ / blockSize) * blockSize),
        max: new Vec3(Math.ceil(maxX / blockSize) * blockSize, Math.ceil(maxY / blockSize) * blockSize, Math.ceil(maxZ / blockSize) * blockSize)
    };
}

/**
 * Set up the common voxelization pipeline used by both filterCluster and filterFloaters.
 *
 * Transforms columns to world space, computes Gaussian extents, builds a BVH,
 * creates a GPU device, and uploads all Gaussians.
 *
 * @param dataTable - Input Gaussian splat data.
 * @param createDevice - Function to create a GPU device for voxelization.
 * @returns Context containing all shared resources.
 */
const setupVoxelFilter = async (dataTable, createDevice) => {
    const voxelColumns = [
        'x', 'y', 'z',
        'rot_0', 'rot_1', 'rot_2', 'rot_3',
        'scale_0', 'scale_1', 'scale_2',
        'opacity'
    ];
    const delta = computeWriteTransform(dataTable.transform, Transform.IDENTITY);
    const cols = transformColumns(dataTable, voxelColumns, delta);
    const missing = voxelColumns.filter(name => !cols.has(name));
    if (missing.length > 0) {
        throw new Error(`setupVoxelFilter: input DataTable is missing required columns: ${missing.join(', ')}`);
    }
    const pcDataTable = new DataTable(voxelColumns.map(name => new Column(name, cols.get(name))));
    const extentsResult = computeGaussianExtents(pcDataTable);
    const sceneBounds = extentsResult.sceneBounds;
    const bvh = new GaussianBVH(pcDataTable, extentsResult.extents);
    const device = await createDevice();
    let gpuVoxelization = null;
    try {
        gpuVoxelization = new GpuVoxelization(device);
        gpuVoxelization.uploadAllGaussians(pcDataTable, extentsResult.extents);
    }
    catch (e) {
        gpuVoxelization?.destroy();
        throw e;
    }
    return { pcDataTable, extentsResult, sceneBounds, bvh, gpuVoxelization };
};
/**
 * Build GaussianColumns from a VoxelFilterContext.
 *
 * @param ctx - Voxel filter context.
 * @returns Column arrays for Gaussian evaluation.
 */
const buildGaussianColumns = (ctx) => ({
    posX: ctx.pcDataTable.getColumnByName('x').data,
    posY: ctx.pcDataTable.getColumnByName('y').data,
    posZ: ctx.pcDataTable.getColumnByName('z').data,
    rotW: ctx.pcDataTable.getColumnByName('rot_0').data,
    rotX: ctx.pcDataTable.getColumnByName('rot_1').data,
    rotY: ctx.pcDataTable.getColumnByName('rot_2').data,
    rotZ: ctx.pcDataTable.getColumnByName('rot_3').data,
    scaleX: ctx.pcDataTable.getColumnByName('scale_0').data,
    scaleY: ctx.pcDataTable.getColumnByName('scale_1').data,
    scaleZ: ctx.pcDataTable.getColumnByName('scale_2').data,
    opacity: ctx.pcDataTable.getColumnByName('opacity').data,
    extentX: ctx.extentsResult.extents.getColumnByName('extent_x').data,
    extentY: ctx.extentsResult.extents.getColumnByName('extent_y').data,
    extentZ: ctx.extentsResult.extents.getColumnByName('extent_z').data
});
/**
 * Build BlockGridParams from grid bounds and voxel size.
 *
 * @param gridBounds - Block-aligned grid bounds.
 * @param voxelResolution - Size of each voxel in world units.
 * @returns Block grid parameters.
 */
const buildBlockGridParams = (gridBounds, voxelResolution) => {
    const blockSize = 4 * voxelResolution;
    const numBlocksX = Math.round((gridBounds.max.x - gridBounds.min.x) / blockSize);
    const numBlocksY = Math.round((gridBounds.max.y - gridBounds.min.y) / blockSize);
    const numBlocksZ = Math.round((gridBounds.max.z - gridBounds.min.z) / blockSize);
    return {
        gridMinX: gridBounds.min.x,
        gridMinY: gridBounds.min.y,
        gridMinZ: gridBounds.min.z,
        blockSize,
        voxelResolution,
        numBlocksX,
        numBlocksY,
        numBlocksZ,
        strideY: numBlocksX,
        strideZ: numBlocksX * numBlocksY
    };
};

const EMPTY = -1;
/**
 * Open-addressing hash map for voxel block masks backed by typed arrays.
 * Replaces Map<number, [number, number]> to eliminate V8 Map overhead and
 * per-entry tuple allocations that cause GC pressure.
 *
 * Keys are non-negative block indices. Values are lo/hi uint32 mask pairs.
 * Uses Fibonacci hashing with linear probing and backward-shift deletion.
 */
class BlockMaskMap {
    keys;
    lo;
    hi;
    _size;
    _capacity;
    _mask;
    constructor(initialCapacity = 4096) {
        const cap = 1 << (32 - Math.clz32(Math.max(15, initialCapacity - 1)));
        this._capacity = cap;
        this._mask = cap - 1;
        this._size = 0;
        this.keys = new Int32Array(cap).fill(EMPTY);
        this.lo = new Uint32Array(cap);
        this.hi = new Uint32Array(cap);
    }
    get size() {
        return this._size;
    }
    /**
     * Find the slot for a key. If the key exists, keys[slot] === key.
     * If the key doesn't exist, keys[slot] === -1 (empty slot for insertion).
     *
     * @param key - Block index to look up.
     * @returns Slot index into keys/lo/hi arrays.
     */
    slot(key) {
        const mask = this._mask;
        let i = (Math.imul(key, 0x9E3779B9) >>> 0) & mask;
        while (true) {
            const k = this.keys[i];
            if (k === key || k === EMPTY)
                return i;
            i = (i + 1) & mask;
        }
    }
    has(key) {
        return this.keys[this.slot(key)] !== EMPTY;
    }
    /**
     * Insert at a slot known to be empty (keys[slot] === -1).
     * Caller must have obtained slot via slot() and verified it is empty.
     *
     * @param slot - Empty slot index.
     * @param key - Block index to insert.
     * @param loVal - Lower 32 bits of voxel mask.
     * @param hiVal - Upper 32 bits of voxel mask.
     */
    insertAt(slot, key, loVal, hiVal) {
        this.keys[slot] = key;
        this.lo[slot] = loVal;
        this.hi[slot] = hiVal;
        this._size++;
        if (this._size > ((this._capacity * 0.7) | 0)) {
            this._grow();
        }
    }
    /**
     * Set key to lo/hi values. Inserts if key doesn't exist, updates if it does.
     *
     * @param key - Block index.
     * @param loVal - Lower 32 bits of voxel mask.
     * @param hiVal - Upper 32 bits of voxel mask.
     */
    set(key, loVal, hiVal) {
        let s = this.slot(key);
        if (this.keys[s] === EMPTY) {
            this.keys[s] = key;
            this._size++;
            if (this._size > ((this._capacity * 0.7) | 0)) {
                this._grow();
                s = this.slot(key);
            }
        }
        this.lo[s] = loVal;
        this.hi[s] = hiVal;
    }
    /**
     * Remove entry at slot using backward-shift deletion.
     * Maintains probe chain integrity without tombstones.
     *
     * @param slot - Slot index of the entry to remove.
     */
    removeAt(slot) {
        this._size--;
        const mask = this._mask;
        let i = slot;
        let j = slot;
        while (true) {
            j = (j + 1) & mask;
            if (this.keys[j] === EMPTY)
                break;
            const k = ((Math.imul(this.keys[j], 0x9E3779B9) >>> 0) & mask);
            if ((i < j) ? (k <= i || k > j) : (k <= i && k > j)) {
                this.keys[i] = this.keys[j];
                this.lo[i] = this.lo[j];
                this.hi[i] = this.hi[j];
                i = j;
            }
        }
        this.keys[i] = EMPTY;
    }
    delete(key) {
        const s = this.slot(key);
        if (this.keys[s] !== EMPTY) {
            this.removeAt(s);
        }
    }
    clear() {
        this.keys.fill(EMPTY);
        this._size = 0;
    }
    forEach(fn) {
        const keys = this.keys;
        const cap = this._capacity;
        for (let i = 0; i < cap; i++) {
            if (keys[i] !== EMPTY) {
                fn(keys[i], this.lo[i], this.hi[i]);
            }
        }
    }
    clone() {
        const c = new BlockMaskMap(this._capacity);
        c.keys.set(this.keys);
        c.lo.set(this.lo);
        c.hi.set(this.hi);
        c._size = this._size;
        return c;
    }
    _grow() {
        const oldKeys = this.keys;
        const oldLo = this.lo;
        const oldHi = this.hi;
        const oldCap = this._capacity;
        this._capacity *= 2;
        this._mask = this._capacity - 1;
        this.keys = new Int32Array(this._capacity).fill(EMPTY);
        this.lo = new Uint32Array(this._capacity);
        this.hi = new Uint32Array(this._capacity);
        this._size = 0;
        for (let i = 0; i < oldCap; i++) {
            if (oldKeys[i] !== EMPTY) {
                const s = this.slot(oldKeys[i]);
                this.keys[s] = oldKeys[i];
                this.lo[s] = oldLo[i];
                this.hi[s] = oldHi[i];
                this._size++;
            }
        }
    }
}

const SOLID_LO = 0xFFFFFFFF >>> 0;
const SOLID_HI = 0xFFFFFFFF >>> 0;
const BLOCK_EMPTY = 0;
const BLOCK_SOLID = 1;
const BLOCK_MIXED = 2;
// Face bitmasks for the 6 faces of a 4x4x4 block.
// bitIdx layout: lx + (ly << 2) + (lz << 4), lo = bits 0-31, hi = bits 32-63.
// Each pair [lo, hi] selects the 16 voxels on one face.
const FACE_MASKS_LO = [
    0x11111111 >>> 0, // -X: lx=0
    0x88888888 >>> 0, // +X: lx=3
    0x000F000F >>> 0, // -Y: ly=0
    0xF000F000 >>> 0, // +Y: ly=3
    0x0000FFFF >>> 0, // -Z: lz=0
    0x00000000 >>> 0 // +Z: lz=3
];
